export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;
  const tossedHeight = launchSpeed * t - (gravity * t * t) / 2;

  const dropHeld = t < apexTime;
  const dropVelocity = dropHeld ? 0 : -gravity * (t - apexTime);
  const dropAcceleration = dropHeld ? 0 : -gravity;
  const dropHeight = dropHeld ? apexHeight : tossedHeight;

  const getStateText = (t, apexTime) => {
    const dt = t - apexTime;
    if (dt < -0.2) return "Rising";
    if (dt <= 0.2) return "At the top";
    if (t < apexTime * 2) return "Falling";
    return "At launch height";
  };

  const tossState = getStateText(t, apexTime);
  const dropState = dropHeld ? "Held in place" : (t - apexTime < 0.05 ? "Just released" : "Falling together");

  const objects = [];

  // Lanes
  objects.push(...sdk.panel({ x: 30, y: 50, w: 270, h: 320, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 330, y: 50, w: 270, h: 320, title: "Drop lane", state: dropState, id: "lane.drop" }));

  // Scale mapping: 0 to 2.2 m mapped to pixel y from 330 down to 90 (height 240 px)
  const H_MAX = 2.2;
  const Y_BASE = 350;
  const H_PIX = 240;
  const toY = (h) => Y_BASE - (h / H_MAX) * H_PIX;

  const tossY = toY(Math.max(0, tossedHeight));
  const dropY = toY(Math.max(0, dropHeight));
  const apexY = toY(apexHeight);

  // Balls
  objects.push(sdk.circle("ball.toss", 165, tossY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 465, dropY, 28, { role: "output" }));

  // Gate at apex
  if (dropHeld) {
    objects.push(...sdk.gate("gate", 465, apexY, { open: false, w: 40, label: "Apex gate" }));
  }

  // Vectors
  objects.push(...sdk.vector("vec.v.toss", { x: 130, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: 200, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: 430, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: 500, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  // Callouts
  objects.push(...sdk.callout(80, tossY - 30, [`v: ${sdk.format(tossedVelocity)} m/s`, `a: ${sdk.format(tossedAcceleration)} m/s^2`], { id: "callout.toss" }));
  objects.push(...sdk.callout(380, dropY - 30, [`v: ${sdk.format(dropVelocity)} m/s`, `a: ${sdk.format(dropAcceleration)} m/s^2`], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
